def manipulate_query_string(url, **qs):
    if "?" in url:
        url, current_qs = url.split("?", 1)
        qs = dict(parse_qsl(current_qs), **qs)
    qs = [(key, value) for (key, value) in qs.items() if value is not None]
    if qs:
        return "%s?%s" % (url, urlencode(qs))
    else:
        return url
class OrderSetStatusView(DetailView):
    def post(self, request, *args, **kwargs):
        order = self.object = self.get_object()
        new_status = OrderStatus.objects.get(pk=int(request.POST["status"]))
        old_status = order.status
        if new_status.role == OrderStatusRole.COMPLETE and not order.can_set_complete():
            raise Problem(_("Unable to set order as completed at this point."))
        if new_status.role == OrderStatusRole.CANCELED and not order.can_set_canceled():
            raise Problem(_("You can't cancel orders that are paid, shipped, or already canceled."))
        order.status = new_status
        order.save(update_fields=("status",))
        message = _("Order status changed: from `{old_status}` to `{new_status}`.").format(
            old_status=old_status, new_status=new_status
        )
        order.add_log_entry(message, user=request.user, identifier="status_change")
        messages.success(self.request, message)
        return HttpResponseRedirect(get_model_url(self.get_object()))
class EditObjectView(View):
    def get(self, request):
        model_name = request.GET.get("model")
        object_id = request.GET.get("pk", request.GET.get("id"))
        if not model_name or not object_id:
            return HttpResponseBadRequest(_("Invalid object."))
        url = None
        try:
            model = apps.get_model(model_name)
        except LookupError:
            return HttpResponseBadRequest(_("Invalid model."))
        instance = model.objects.filter(pk=object_id).first()
        if instance:
            try:
                try:
                    url = get_model_url(
                        instance, kind="edit", user=request.user, shop=get_shop(request), raise_permission_denied=True
                    )
                except NoModelUrl:
                    try:
                        url = get_model_url(
                            instance,
                            kind="detail",
                            user=request.user,
                            shop=get_shop(request),
                            raise_permission_denied=True,
                        )
                    except NoModelUrl:
                        pass
            except PermissionDenied as exception:
                from shuup.utils.django_compat import force_text
                raise Problem(force_text(exception))
            if url:
                if request.GET.get("mode"):
                    url = "{}?mode={}".format(url, request.GET["mode"])
                return HttpResponseRedirect(url)
        raise Http404(_("Object not found."))
