class CheckoutProcess(object):
    def get_current_phase(self, requested_phase_identifier):
        found = False
        for phase in self.phases:
            if phase.is_valid():
                phase.process()
            if found or not requested_phase_identifier or requested_phase_identifier == phase.identifier:
                found = True
                if not phase.should_skip():
                    return phase
            if not phase.should_skip() and not phase.is_valid():
                return phase
        raise Http404("Error! Phase with identifier `%s` not found." % requested_phase_identifier)

