        path = jupyter_config_path()
        if self.config_dir not in path:
            path.insert(0, self.config_dir)
        return path
    def _data_dir_default(self):
        d = jupyter_data_dir()
        ensure_dir_exists(d, mode=0o700)
        return d
    def _runtime_dir_default(self):
        rd = jupyter_runtime_dir()
