            raise TypeError(f"Incorrect type: expected Request, Response or Failure, got {type(result)}: {result!r}")
        if isinstance(result, Request):
            self.crawl(result)
            return None
        d = self.scraper.enqueue_scrape(result, request, self.spider)
        d.addErrback(
            lambda f: logger.error(
