class NicotineCore:
    def send_message_to_peer(self, user, message, address=None):
        """ Sends message to a peer. Used primarily when we know the username of a peer,
        but don't have an active connection. """
        conn = None
        if message.__class__ is not slskmessages.FileRequest:
            """ Check if there's already a connection object for the specified username """
            for i in self.peerconns:
                if i.username == user and i.conn_type == 'P':
                    conn = i
                    log.add_conn("Found existing connection of type %(type)s for user %(user)s, using it.", {
                        'type': i.conn_type,
                        'user': user
                    })
                    break
        if conn is not None and conn.conn is not None:
            """ We have initiated a connection previously, and it's ready """
            conn.msgs.append(message)
            self.process_conn_messages(conn, conn.conn)
        elif conn is not None:
            """ Connection exists but is not ready yet, add new messages to it """
            conn.msgs.append(message)
        else:
            """ This is a new peer, initiate a connection """
            self.initiate_connection_to_peer(user, message, address)
        log.add_conn("Sending message of type %(type)s to user %(user)s", {
            'type': message.__class__,
            'user': user
        })
    def connect_to_peer_direct(self, user, addr, message_type, init=None):
        """ Initiate a connection with a peer directly """
        self.queue.append(slskmessages.InitPeerConn(None, addr, init))
        log.add_conn("Attempting direct connection of type %(type)s to user %(user)s %(addr)s", {
            'type': message_type,
            'user': user,
            'addr': addr
        })
    def get_user_stats(self, msg, log_contents=True):
        """ Server code: 36 """
        if log_contents:
            log.add_msg_contents(msg)
        if msg.user == config.sections["server"]["login"]:
            self.transfers.upload_speed = msg.avgspeed
            self.max_distrib_children = msg.avgspeed // self.distrib_parent_speed_ratio
        self.interests.get_user_stats(msg)
        self.userinfo.get_user_stats(msg)
        self.userlist.get_user_stats(msg)
        self.chatrooms.get_user_stats(msg)
        stats = {
            'avgspeed': msg.avgspeed,
            'uploadnum': msg.uploadnum,
            'files': msg.files,
            'dirs': msg.dirs,
        }
        self.pluginhandler.user_stats_notification(msg.user, stats)
class Transfers:
    def queue_upload(self, msg):
        """ Peer remotely queued a download (upload here). This is the modern replacement to
        a TransferRequest with direction 0 (download request). We will initiate the upload of
        the queued file later. """
        user = msg.conn.init.target_user
        addr = msg.conn.addr[0]
        real_path = self.core.shares.virtual2real(msg.file)
        if not self.file_is_upload_queued(user, msg.file):
            limits = True
            if self.config.sections["transfers"]["friendsnolimits"]:
                friend = user in (i[0] for i in self.config.sections["server"]["userlist"])
                if friend:
                    limits = False
            checkuser, reason = self.core.network_filter.check_user(user, addr)
            if not checkuser:
                self.queue.append(
                    slskmessages.UploadDenied(conn=msg.conn.conn, file=msg.file, reason=reason)
                )
            elif limits and self.queue_limit_reached(user):
                self.queue.append(
                    slskmessages.UploadDenied(conn=msg.conn.conn, file=msg.file, reason="Too many megabytes")
                )
            elif limits and self.file_limit_reached(user):
                self.queue.append(
                    slskmessages.UploadDenied(conn=msg.conn.conn, file=msg.file, reason="Too many files")
                )
            elif self.core.shares.file_is_shared(user, msg.file, real_path):
                newupload = Transfer(
                    user=user, filename=msg.file,
                    path=os.path.dirname(real_path), status="Queued",
                    timequeued=time.time(), size=self.get_file_size(real_path)
                )
                self._append_upload(user, msg.file, newupload)
                if self.uploadsview:
                    self.uploadsview.update(newupload)
                self.core.pluginhandler.upload_queued_notification(user, msg.file, real_path)
                self.check_upload_queue()
            else:
                self.queue.append(
                    slskmessages.UploadDenied(conn=msg.conn.conn, file=msg.file, reason="File not shared.")
                )
        log.add_transfer("QueueUpload request: User %(user)s, %(msg)s", {
            'user': user,
            'msg': str(vars(msg))
        })
    def transfer_request_downloads(self, msg, user):
        filename = msg.file
        size = msg.filesize
        if self.get_existing_download_path(user, filename, "", size):
            cancel_reason = "Complete"
            accepted = False
        else:
            cancel_reason = "Cancelled"
            accepted = True
            for i in self.downloads:
                if i.filename == filename and user == i.user:
                    status = i.status
                    if status == "Finished":
                        cancel_reason = "Complete"
                        accepted = False
                        break
                    if status in ("Paused", "Filtered"):
                        accepted = False
                        break
                    """ If the file is larger than 2GB, the SoulseekQt client seems to
                    send a malformed file size (0 bytes) in the TransferRequest response.
                    In that case, we rely on the cached, correct file size we received when
                    we initially added the download. """
                    if msg.filesize > 0:
                        i.size = size
                    i.req = msg.req
                    i.status = "Getting status"
                    self.transfer_request_times[i] = time.time()
                    if self.downloadsview:
                        self.downloadsview.update(i)
                    response = slskmessages.TransferResponse(None, 1, req=i.req)
                    return response
        if accepted and self.can_upload(user):
            path = ""
            if self.config.sections["transfers"]["uploadsinsubdirs"]:
                parentdir = msg.file.replace('/', '\\').split('\\')[-2]
                path = os.path.join(self.config.sections["transfers"]["uploaddir"], user, parentdir)
            transfer = Transfer(
                user=user, filename=msg.file, path=path,
                status="Queued", size=msg.filesize, req=msg.req
            )
            self.downloads.appendleft(transfer)
            self.core.watch_user(user)
            response = slskmessages.TransferResponse(None, 0, reason="Queued", req=transfer.req)
            if self.downloadsview:
                self.downloadsview.update(transfer)
        else:
            response = slskmessages.TransferResponse(None, 0, reason=cancel_reason, req=msg.req)
            log.add_transfer("Denied file request: User %(user)s, %(msg)s", {
                'user': user,
                'msg': str(vars(msg))
            })
        return response
