        interface = config.sections["server"]["interface"]
        self.protothread = slskproto.SlskProtoThread(
            self.network_callback, self.queue, self.bindip, interface, self.port, port_range, self.network_filter, self)
        self.add_upnp_portmapping()
        self.pluginhandler = PluginHandler(self, config)
        connect_ready = not config.need_config()
        if not connect_ready:
            log.add(_("You need to specify a username and password before connecting…"))
        return connect_ready
    def initiate_connection_to_peer(self, user, message, address=None):
        """ Prepare to initiate a connection with a peer """
        if message.__class__ is slskmessages.FileRequest:
            message_type = 'F'
        elif message.__class__ is slskmessages.DistribRequest:
            message_type = 'D'
        else:
            message_type = 'P'
        init = slskmessages.PeerInit(
            init_user=config.sections["server"]["login"], target_user=user, conn_type=message_type, token=0)
        addr = None
        if user == config.sections["server"]["login"]:
            addr = (self.protothread.bindip or '127.0.0.1', self.protothread.listenport)
        elif user in self.users:
            addr = self.users[user].addr
        elif address is not None:
            self.users[user] = UserAddr(status=-1, addr=address)
            addr = address
        if addr is None:
            self.queue.append(slskmessages.GetPeerAddress(user))
            log.add_conn("Requesting address for user %(user)s", {
                'user': user
            })
        else:
            self.connect_to_peer_direct(user, addr, message_type, init)
        self.peerconns.append(
            PeerConnection(
                addr=addr,
                username=user,
                msgs=[message],
                init=init
            )
        )
    def server_disconnect(self):
        if self.server_conn is None:
            return
        host, port = self.server_address
        log.add(
            _("Disconnected from server %(host)s:%(port)s"), {
                'host': host,
                'port': port
            })
        self.exit.set()
        if not self.manual_disconnect:
            self.set_server_timer()
        else:
            self.manual_disconnect = False
        self.server_conn = None
        self.server_address = None
        self.logged_in = False
        self.peerconns.clear()
        self.out_indirect_conn_request_times.clear()
        self.watched_users.clear()
        self.users.clear()
        self.pluginhandler.server_disconnect_notification(self.manual_disconnect)
        self.transfers.server_disconnect()
        self.search.server_disconnect()
        self.userlist.server_disconnect()
        self.chatrooms.server_disconnect()
        self.privatechats.server_disconnect()
        self.userinfo.server_disconnect()
        self.userbrowse.server_disconnect()
        if self.ui_callback:
            self.ui_callback.server_disconnect()
class ChatEntry:
    def on_enter(self, *_args):
        if not self.frame.np.logged_in:
            return
        text = self.entry.get_text()
        if not text:
            return
        if is_alias(text):
            alias_text = get_alias(text)
            if not alias_text:
                log.add(_('Alias "%s" returned nothing'), text)
                return
            text = alias_text
        is_double_slash_cmd = text.startswith("//")
        is_single_slash_cmd = (text.startswith("/") and not is_double_slash_cmd)
        if not is_single_slash_cmd or text.startswith("/me"):
            self.entry.set_text("")
            if is_double_slash_cmd:
                text = text[1:]
            self.send_message(self.entity, text)
            return
        cmd_split = text.split(maxsplit=1)
        cmd = cmd_split[0]
        if cmd + " " not in self.command_list:
            log.add(_("Command %s is not recognized"), cmd)
            return
        self.entry.set_text("")
        if len(cmd_split) == 2:
            args = arg_self = cmd_split[1]
        else:
            args = ""
            arg_self = "" if self.is_chatroom else self.entity
        if cmd in ("/alias", "/al"):
            parent = self.frame.np.chatrooms if self.is_chatroom else self.frame.np.privatechats
            parent.echo_message(self.entity, add_alias(args))
            if config.sections["words"]["aliases"]:
                self.frame.update_completions()
        elif cmd in ("/unalias", "/un"):
            parent = self.frame.np.chatrooms if self.is_chatroom else self.frame.np.privatechats
            parent.echo_message(self.entity, unalias(args))
            if config.sections["words"]["aliases"]:
                self.frame.update_completions()
        elif cmd in ("/w", "/whois", "/info"):
            if arg_self:
                self.frame.np.userinfo.request_user_info(arg_self)
                self.frame.change_main_page("userinfo")
        elif cmd in ("/b", "/browse"):
            if arg_self:
                self.frame.np.userbrowse.browse_user(arg_self)
                self.frame.change_main_page("userbrowse")
        elif cmd == "/ip":
            if arg_self:
                self.frame.np.request_ip_address(arg_self)
        elif cmd == "/pm":
            if args:
                self.frame.np.privatechats.show_user(args)
                self.frame.change_main_page("private")
        elif cmd in ("/m", "/msg"):
            if args:
                args_split = args.split(" ", maxsplit=1)
                user = args_split[0]
                msg = None
                if len(args_split) == 2:
                    msg = args_split[1]
                if msg:
                    self.frame.np.privatechats.show_user(user)
                    self.frame.np.privatechats.send_message(user, msg)
                    self.frame.change_main_page("private")
        elif cmd in ("/s", "/search"):
            if args:
                self.frame.np.search.do_search(args, "global")
                self.frame.change_main_page("search")
        elif cmd in ("/us", "/usearch"):
            args_split = args.split(" ", maxsplit=1)
            if len(args_split) == 2:
                self.frame.np.search.do_search(args_split[1], "user", user=args_split[0])
                self.frame.change_main_page("search")
        elif cmd in ("/rs", "/rsearch"):
            if args:
                self.frame.np.search.do_search(args, "rooms")
                self.frame.change_main_page("search")
        elif cmd in ("/bs", "/bsearch"):
            if args:
                self.frame.np.search.do_search(args, "buddies")
                self.frame.change_main_page("search")
        elif cmd in ("/j", "/join"):
            if args:
                self.frame.np.queue.append(slskmessages.JoinRoom(args))
        elif cmd in ("/l", "/leave", "/p", "/part"):
            if args:
                self.frame.np.queue.append(slskmessages.LeaveRoom(args))
            else:
                self.frame.np.queue.append(slskmessages.LeaveRoom(self.entity))
        elif cmd in ("/ad", "/add", "/buddy"):
            if args:
                self.frame.np.userlist.add_user(args)
        elif cmd in ("/rem", "/unbuddy"):
            if args:
                self.frame.np.userlist.remove_user(args)
        elif cmd == "/ban":
            if args:
                self.frame.np.network_filter.ban_user(args)
        elif cmd == "/ignore":
            if args:
                self.frame.np.network_filter.ignore_user(args)
        elif cmd == "/ignoreip":
            if args:
                self.frame.np.network_filter.ignore_ip(args)
        elif cmd == "/unban":
            if args:
                self.frame.np.network_filter.unban_user(args)
        elif cmd == "/unignore":
            if args:
                self.frame.np.network_filter.unignore_user(args)
        elif cmd == "/ctcpversion":
            if arg_self:
                self.frame.np.privatechats.show_user(arg_self)
                self.frame.np.privatechats.send_message(arg_self, self.frame.np.privatechats.CTCP_VERSION)
        elif cmd in ("/clear", "/cl"):
            if self.is_chatroom:
                parent = self.frame.chatrooms.pages[self.entity]
            else:
                parent = self.frame.privatechat.pages[self.entity]
            parent.chat_textview.clear()
        elif cmd in ("/a", "/away"):
            self.frame.on_away()
        elif cmd in ("/q", "/quit", "/exit"):
            self.frame.np.quit()
        elif cmd in ("/c", "/close"):
            self.frame.privatechat.pages[self.entity].on_close()
        elif cmd == "/now":
            self.frame.np.now_playing.display_now_playing(
                callback=lambda np_message: self.send_message(self.entity, np_message))
        elif cmd == "/rescan":
            self.frame.np.shares.rescan_shares()
        elif cmd == "/toggle":
            if args:
                self.frame.np.pluginhandler.toggle_plugin(args)
        elif self.is_chatroom:
            self.frame.np.pluginhandler.trigger_public_command_event(self.entity, cmd[1:], args)
        elif not self.is_chatroom:
            self.frame.np.pluginhandler.trigger_private_command_event(self.entity, cmd[1:], args)
class RoomList(ServerMessage):
    def get_rooms(self, originalpos, message):
        try:
            pos, numrooms = self.get_object(message, int, originalpos)
            rooms = []
            for i in range(numrooms):
                pos, room = self.get_object(message, str, pos)
                rooms.append([room, None])
            pos, numusers = self.get_object(message, int, pos)
            for i in range(numusers):
                pos, usercount = self.get_object(message, int, pos)
                rooms[i][1] = usercount
            return (pos, rooms)
        except Exception as error:
            log.add("Exception during parsing %(area)s: %(exception)s", {'area': 'RoomList', 'exception': error})
            return (originalpos, [])
