def _pack_arguments(fn_type, args, context):
    args_tuple_t = TupleType([x.typ for x in args])
    args_as_tuple = IRnode.from_list(["multi"] + [x for x in args], typ=args_tuple_t)
    args_abi_t = args_tuple_t.abi_type
    dst_tuple_t = TupleType(
        [new_type_to_old_type(typ) for typ in fn_type.arguments.values()][: len(args)]
    )
    check_assign(dummy_node_for_type(dst_tuple_t), args_as_tuple)
    if fn_type.return_type is not None:
        return_abi_t = calculate_type_for_external_return(fn_type.return_type).abi_type
        buflen = max(args_abi_t.size_bound(), return_abi_t.size_bound())
    else:
        buflen = args_abi_t.size_bound()
    buflen += 32
    buf_t = get_type_for_exact_size(buflen)
    buf = context.new_internal_variable(buf_t)
    args_ofst = buf + 28
    args_len = args_abi_t.size_bound() + 4
    abi_signature = fn_type.name + dst_tuple_t.abi_type.selector_name()
    pack_args = ["seq"]
    pack_args.append(["mstore", buf, util.abi_method_id(abi_signature)])
    if len(args) != 0:
        pack_args.append(abi_encode(buf + 32, args_as_tuple, context, bufsz=buflen))
    return buf, pack_args, args_ofst, args_len
def _unpack_returndata(buf, fn_type, call_kwargs, contract_address, context, expr):
    ast_return_t = fn_type.return_type
    if ast_return_t is None:
        return ["pass"], 0, 0
    return_t = new_type_to_old_type(ast_return_t)
    wrapped_return_t = calculate_type_for_external_return(return_t)
    abi_return_t = wrapped_return_t.abi_type
    min_return_size = abi_return_t.min_size()
    max_return_size = abi_return_t.size_bound()
    assert 0 < min_return_size <= max_return_size
    ret_ofst = buf
    ret_len = max_return_size
    encoding = Encoding.ABI
    buf = IRnode.from_list(
        buf,
        typ=wrapped_return_t,
        location=MEMORY,
        encoding=encoding,
        annotation=f"{expr.node_source_code} returndata buffer",
    )
    unpacker = ["seq"]
    if not call_kwargs.skip_contract_check:
        unpacker.append(["assert", ["ge", "returndatasize", min_return_size]])
    assert isinstance(wrapped_return_t, TupleType)
    if needs_clamp(wrapped_return_t, encoding):
        return_buf = context.new_internal_variable(wrapped_return_t)
        return_buf = IRnode.from_list(return_buf, typ=wrapped_return_t, location=MEMORY)
        unpacker.append(make_setter(return_buf, buf))
    else:
        return_buf = buf
    if call_kwargs.default_return_value is not None:
        override_value = wrap_value_for_external_return(call_kwargs.default_return_value)
        stomp_return_buffer = ["seq"]
        if not call_kwargs.skip_contract_check:
            stomp_return_buffer.append(_extcodesize_check(contract_address))
        stomp_return_buffer.append(make_setter(return_buf, override_value))
        unpacker = ["if", ["eq", "returndatasize", 0], stomp_return_buffer, unpacker]
    unpacker = ["seq", unpacker, return_buf]
    return unpacker, ret_ofst, ret_len
def _parse_kwargs(call_expr, context):
    from vyper.codegen.expr import Expr
    def _bool(x):
        assert x.value in (0, 1), "type checker missed this"
        return bool(x.value)
    call_kwargs = {kw.arg: Expr(kw.value, context).ir_node for kw in call_expr.keywords}
    ret = _CallKwargs(
        value=unwrap_location(call_kwargs.pop("value", IRnode(0))),
        gas=unwrap_location(call_kwargs.pop("gas", IRnode("gas"))),
        skip_contract_check=_bool(call_kwargs.pop("skip_contract_check", IRnode(0))),
        default_return_value=call_kwargs.pop("default_return_value", None),
    )
    if len(call_kwargs) != 0:
        raise TypeCheckFailure(f"Unexpected keyword arguments: {call_kwargs}")
    return ret
def _extcodesize_check(address):
    return ["assert", ["extcodesize", address]]
def ir_for_external_call(call_expr, context):
    from vyper.codegen.expr import Expr
    contract_address = Expr.parse_value_expr(call_expr.func.value, context)
    call_kwargs = _parse_kwargs(call_expr, context)
    args_ir = [Expr(x, context).ir_node for x in call_expr.args]
    assert isinstance(contract_address.typ, InterfaceType)
    fn_type = call_expr.func._metadata["type"]
    assert fn_type.min_arg_count <= len(args_ir) <= fn_type.max_arg_count
    ret = ["seq"]
    buf, arg_packer, args_ofst, args_len = _pack_arguments(fn_type, args_ir, context)
    ret_unpacker, ret_ofst, ret_len = _unpack_returndata(
        buf, fn_type, call_kwargs, contract_address, context, call_expr
    )
    ret += arg_packer
    if fn_type.return_type is None and not call_kwargs.skip_contract_check:
        ret.append(_extcodesize_check(contract_address))
    gas = call_kwargs.gas
    value = call_kwargs.value
    use_staticcall = fn_type.mutability in (StateMutability.VIEW, StateMutability.PURE)
    if context.is_constant():
        assert use_staticcall, "typechecker missed this"
    if use_staticcall:
        call_op = ["staticcall", gas, contract_address, args_ofst, args_len, buf, ret_len]
    else:
        call_op = ["call", gas, contract_address, value, args_ofst, args_len, buf, ret_len]
    ret.append(check_external_call(call_op))
    return_t = None
    if fn_type.return_type is not None:
        return_t = new_type_to_old_type(fn_type.return_type)
        ret.append(ret_unpacker)
    return IRnode.from_list(ret, typ=return_t, location=MEMORY)
MEMORY = AddrSpace("memory", 32, "mload", "mstore")
CALLDATA = AddrSpace("calldata", 32, "calldataload")
def new_type_to_old_type(typ: new.BasePrimitive) -> old.NodeType:
    if isinstance(typ, new.BoolDefinition):
        return old.BaseType("bool")
    if isinstance(typ, new.AddressDefinition):
        return old.BaseType("address")
    if isinstance(typ, new.InterfaceDefinition):
        return old.InterfaceType(typ._id)
    if isinstance(typ, new.BytesMDefinition):
        m = typ._length
        return old.BaseType(f"bytes{m}")
    if isinstance(typ, new.BytesArrayDefinition):
        return old.ByteArrayType(typ.length)
    if isinstance(typ, new.StringDefinition):
        return old.StringType(typ.length)
    if isinstance(typ, new.DecimalDefinition):
        return old.BaseType("decimal")
    if isinstance(typ, new.SignedIntegerAbstractType):
        bits = typ._bits
        return old.BaseType("int" + str(bits))
    if isinstance(typ, new.UnsignedIntegerAbstractType):
        bits = typ._bits
        return old.BaseType("uint" + str(bits))
    if isinstance(typ, new.ArrayDefinition):
        return old.SArrayType(new_type_to_old_type(typ.value_type), typ.length)
    if isinstance(typ, new.DynamicArrayDefinition):
        return old.DArrayType(new_type_to_old_type(typ.value_type), typ.length)
    if isinstance(typ, new.TupleDefinition):
        return old.TupleType([new_type_to_old_type(t) for t in typ.value_type])
    if isinstance(typ, new.StructDefinition):
        return old.StructType(
            {n: new_type_to_old_type(t) for (n, t) in typ.members.items()}, typ._id
        )
    if isinstance(typ, new.EnumDefinition):
        return old.EnumType(typ._id, typ.members.copy())
    if isinstance(typ, new.MappingDefinition):
        return old.MappingType(
            new_type_to_old_type(typ.key_type), new_type_to_old_type(typ.value_type)
        )
    raise InvalidType(f"unknown type {typ}")
def check_external_call(call_ir):
    copy_revertdata = ["returndatacopy", 0, 0, "returndatasize"]
    revert = ["revert", 0, "returndatasize"]
    propagate_revert_ir = ["seq", copy_revertdata, revert]
    return ["if", ["iszero", call_ir], propagate_revert_ir]
def _complex_make_setter(left, right):
    if right.value == "~empty" and left.location == MEMORY:
        return mzero(left, left.typ.memory_bytes_required)
    ret = ["seq"]
    if isinstance(left.typ, SArrayType):
        n_items = right.typ.count
        keys = [IRnode.from_list(i, typ="uint256") for i in range(n_items)]
    if isinstance(left.typ, TupleLike):
        keys = left.typ.tuple_keys()
    with left.cache_when_complex("_L") as (b1, left), right.cache_when_complex("_R") as (b2, right):
        for k in keys:
            l_i = get_element_ptr(left, k, array_bounds_check=False)
            r_i = get_element_ptr(right, k, array_bounds_check=False)
            ret.append(make_setter(l_i, r_i))
        return b1.resolve(b2.resolve(IRnode.from_list(ret)))
def ensure_in_memory(ir_var, context):
    """Ensure a variable is in memory. This is useful for functions
    which expect to operate on memory variables.
    """
    if ir_var.location == MEMORY:
        return ir_var
    typ = ir_var.typ
    buf = IRnode.from_list(context.new_internal_variable(typ), typ=typ, location=MEMORY)
    do_copy = make_setter(buf, ir_var)
    return IRnode.from_list(["seq", do_copy, buf], typ=typ, location=MEMORY)
def abi_encode(dst, ir_node, context, bufsz, returns_len=False):
    dst = IRnode.from_list(dst, typ=ir_node.typ, location=MEMORY)
    abi_t = dst.typ.abi_type
    size_bound = abi_t.size_bound()
    assert isinstance(bufsz, int)
    if bufsz < size_bound:
        raise CompilerPanic("buffer provided to abi_encode not large enough")
    if size_bound < dst.typ.memory_bytes_required:
        raise CompilerPanic("Bad ABI size calc")
    annotation = f"abi_encode {ir_node.typ}"
    ir_ret = ["seq"]
    if abi_encoding_matches_vyper(ir_node.typ):
        ir_ret.append(make_setter(dst, ir_node))
        if returns_len:
            assert abi_t.embedded_static_size() == ir_node.typ.memory_bytes_required
            ir_ret.append(abi_t.embedded_static_size())
        return IRnode.from_list(ir_ret, annotation=annotation)
    with ir_node.cache_when_complex("to_encode") as (b1, ir_node), dst.cache_when_complex(
        "dst"
    ) as (b2, dst):
        dyn_ofst = "dyn_ofst"
        if isinstance(ir_node.typ, BaseType):
            ir_ret.append(make_setter(dst, ir_node))
        elif isinstance(ir_node.typ, ByteArrayLike):
            ir_ret.append(make_setter(dst, ir_node))
            ir_ret.append(zero_pad(dst))
        elif isinstance(ir_node.typ, DArrayType):
            ir_ret.append(_encode_dyn_array_helper(dst, ir_node, context))
        elif isinstance(ir_node.typ, (TupleLike, SArrayType)):
            static_ofst = 0
            elems = _deconstruct_complex_type(ir_node)
            for e in elems:
                encode_ir = _encode_child_helper(dst, e, static_ofst, dyn_ofst, context)
                ir_ret.extend(encode_ir)
                static_ofst += e.typ.abi_type.embedded_static_size()
        else:
            raise CompilerPanic(f"unencodable type: {ir_node.typ}")
        if returns_len:
            if not abi_t.is_dynamic():
                ir_ret.append(abi_t.embedded_static_size())
            elif isinstance(ir_node.typ, ByteArrayLike):
                calc_len = ["ceil32", ["add", 32, ["mload", dst]]]
                ir_ret.append(calc_len)
            elif abi_t.is_complex_type():
                ir_ret.append("dyn_ofst")
            else:
                raise CompilerPanic(f"unknown type {ir_node.typ}")
        if abi_t.is_dynamic() and abi_t.is_complex_type():
            dyn_section_start = abi_t.static_size()
            ir_ret = ["with", dyn_ofst, dyn_section_start, ir_ret]
        else:
            pass
        return b1.resolve(b2.resolve(IRnode.from_list(ir_ret, annotation=annotation)))
def _build_adhoc_slice_node(sub: IRnode, start: IRnode, length: IRnode, context: Context) -> IRnode:
    assert length.is_literal, "typechecker failed"
    dst_typ = ByteArrayType(maxlen=length.value)
    np = context.new_internal_variable(dst_typ)
    if sub.value == "~calldata":
        node = [
            "seq",
            ["assert", ["le", ["add", start, length], "calldatasize"]],
            ["mstore", np, length],
            ["calldatacopy", np + 32, start, length],
            np,
        ]
    elif sub.value == "~selfcode":
        node = [
            "seq",
            ["assert", ["le", ["add", start, length], "codesize"]],
            ["mstore", np, length],
            ["codecopy", np + 32, start, length],
            np,
        ]
    else:
        assert sub.value == "~extcode" and len(sub.args) == 1
        node = [
            "with",
            "_extcode_address",
            sub.args[0],
            [
                "seq",
                [
                    "assert",
                    ["le", ["add", start, length], ["extcodesize", "_extcode_address"]],
                ],
                ["mstore", np, length],
                ["extcodecopy", "_extcode_address", np + 32, start, length],
                np,
            ],
        ]
    return IRnode.from_list(node, typ=ByteArrayType(length.value), location=MEMORY)
class Slice(_SimpleBuiltinFunction):
    @validate_inputs
    def build_IR(self, expr, args, kwargs, context):
        src, start, length = args
        if src.value in ADHOC_SLICE_NODE_MACROS:
            return _build_adhoc_slice_node(src, start, length, context)
        is_bytes32 = is_base_type(src.typ, "bytes32")
        if src.location is None:
            assert is_bytes32, src
            src = ensure_in_memory(src, context)
        with src.cache_when_complex("src") as (b1, src), start.cache_when_complex("start") as (
            b2,
            start,
        ), length.cache_when_complex("length") as (b3, length):
            if is_bytes32:
                src_maxlen = 32
            else:
                src_maxlen = src.typ.maxlen
            dst_maxlen = length.value if length.is_literal else src_maxlen
            buflen = dst_maxlen
            if src.location == STORAGE:
                buflen += 32
            assert isinstance(src.typ, ByteArrayLike) or is_bytes32
            if isinstance(src.typ, StringType):
                dst_typ = StringType(maxlen=dst_maxlen)
            else:
                dst_typ = ByteArrayType(maxlen=dst_maxlen)
            buf = context.new_internal_variable(ByteArrayType(buflen))
            dst = IRnode.from_list(buf, typ=dst_typ, location=MEMORY)
            dst_data = bytes_data_ptr(dst)
            if is_bytes32:
                src_len = 32
                src_data = src
            else:
                src_len = get_bytearray_length(src)
                src_data = bytes_data_ptr(src)
            if src.location == STORAGE:
                copy_src = IRnode.from_list(
                    ["add", src_data, ["div", start, 32]],
                    location=src.location,
                )
                copy_dst = IRnode.from_list(
                    ["sub", dst_data, ["mod", start, 32]], location=dst.location
                )
                copy_len = ["add", length, ["mul", 32, ["iszero", ["iszero", ["mod", start, 32]]]]]
                copy_maxlen = buflen
            else:
                copy_src = add_ofst(src_data, start)
                copy_dst = dst_data
                copy_len = length
                copy_maxlen = buflen
            do_copy = copy_bytes(
                copy_dst,
                copy_src,
                copy_len,
                copy_maxlen,
            )
            ret = [
                "seq",
                ["assert", ["le", ["add", start, length], src_len]],
                do_copy,
                ["mstore", dst, length],
                dst,
            ]
            ret = IRnode.from_list(ret, typ=dst_typ, location=MEMORY)
            return b1.resolve(b2.resolve(b3.resolve(ret)))
class Concat(_SimpleBuiltinFunction):
    def build_IR(self, expr, context):
        args = [Expr(arg, context).ir_node for arg in expr.args]
        if len(args) < 2:
            raise StructureException("Concat expects at least two arguments", expr)
        dst_maxlen = sum(
            [
                arg.typ.maxlen if isinstance(arg.typ, ByteArrayLike) else arg.typ._bytes_info.m
                for arg in args
            ]
        )
        if isinstance(args[0].typ, StringType):
            ret_typ = StringType(maxlen=dst_maxlen)
        else:
            ret_typ = ByteArrayType(maxlen=dst_maxlen)
        dst = IRnode.from_list(
            context.new_internal_variable(ret_typ),
            typ=ret_typ,
            location=MEMORY,
            annotation="concat destination",
        )
        ret = ["seq"]
        ofst = "concat_ofst"
        for arg in args:
            dst_data = add_ofst(bytes_data_ptr(dst), ofst)
            if isinstance(arg.typ, ByteArrayLike):
                if arg.typ.maxlen == 0:
                    continue
                with arg.cache_when_complex("arg") as (b1, arg):
                    argdata = bytes_data_ptr(arg)
                    with get_bytearray_length(arg).cache_when_complex("len") as (b2, arglen):
                        do_copy = [
                            "seq",
                            copy_bytes(dst_data, argdata, arglen, arg.typ.maxlen),
                            ["set", ofst, ["add", ofst, arglen]],
                        ]
                        ret.append(b1.resolve(b2.resolve(do_copy)))
            else:
                ret.append(STORE(dst_data, unwrap_location(arg)))
                ret.append(["set", ofst, ["add", ofst, arg.typ._bytes_info.m]])
        ret.append(STORE(dst, ofst))
        ret.append(dst)
        return IRnode.from_list(
            ["with", ofst, 0, ret],
            typ=ret_typ,
            location=MEMORY,
            annotation="concat",
        )
