        g_id = int(request.query_params.get('group', 0))
        if int(g_id) == 0:
            image_list = Image.objects.filter(user=request.user)
        elif int(g_id) == -1:
            image_list = Image.objects.filter(user=request.user, group_id=None)
        else:
            image_list = Image.objects.filter(user=request.user, group_id=g_id)
        page = PageNumberPagination()
        page_images = page.paginate_queryset(image_list,request,view=self)
        serializer = ImageSerializer(page_images,many=True)
        resp = {'code':0,'data':serializer.data,'count':image_list.count()}
        return Response(resp)

class GlancesActions(object):
    def get(self, stat_name):
        """Get the stat_name criticity."""
        try:
            return self.status[stat_name]
        except KeyError:
            return None
    def set(self, stat_name, criticity):
        """Set the stat_name to criticity."""
        self.status[stat_name] = criticity
    def run(self, stat_name, criticity, commands, repeat, mustache_dict=None):
        """Run the commands (in background).
        - stats_name: plugin_name (+ header)
        - criticity: criticity of the trigger
        - commands: a list of command line with optional {{mustache}}
        - If True, then repeat the action
        - mustache_dict: Plugin stats (can be use within {{mustache}})
        Return True if the commands have been ran.
        """
        if (self.get(stat_name) == criticity and not repeat) or \
           not self.start_timer.finished():
            return False
        logger.debug("{} action {} for {} ({}) with stats {}".format(
            "Repeat" if repeat else "Run",
            commands, stat_name, criticity, mustache_dict))
        for cmd in commands:
            if chevron_tag:
                cmd_full = chevron.render(cmd, mustache_dict)
            else:
                cmd_full = cmd
            logger.info("Action triggered for {} ({}): {}".format(stat_name,
                                                                  criticity,
                                                                  cmd_full))
            try:
                ret = secure_popen(cmd_full)
            except OSError as e:
                logger.error("Action error for {} ({}): {}".format(stat_name,
                                                                   criticity,
                                                                   e))
            else:
                logger.debug("Action result for {} ({}): {}".format(stat_name,
                                                                    criticity,
                                                                    ret))
        self.set(stat_name, criticity)
        return True
logger = glances_logger()
def secure_popen(cmd):
    """A more or less secure way to execute system command
    Return: the result of the command OR an error message
    """
    ret = None
    cmd_split_redirect = cmd.split('>')
    if len(cmd_split_redirect) > 2:
        return 'Glances error: Only one file redirection allowed ({})'.format(cmd)
    elif len(cmd_split_redirect) == 2:
        stdout_redirect = cmd_split_redirect[1].strip()
        cmd = cmd_split_redirect[0]
    else:
        stdout_redirect = None
    sub_cmd_stdin = None
    p_last = None
    for sub_cmd in cmd.split('|'):
        sub_cmd_split = [i for i in sub_cmd.split(' ') if i]
        p = Popen(sub_cmd_split,
                  shell=False,
                  stdin=sub_cmd_stdin,
                  stdout=PIPE,
                  stderr=PIPE)
        if p_last is not None:
            p_last.stdout.close()
        p_last = p
        sub_cmd_stdin = p.stdout
    p_ret = p_last.communicate()
    if nativestr(p_ret[1]) == '':
        ret = nativestr(p_ret[0])
        if stdout_redirect is not None:
            with open(stdout_redirect, "w") as stdout_redirect_file:
                stdout_redirect_file.write(ret)
    else:
        ret = nativestr(p_ret[1])
    return ret
class _GlancesCurses(object):
    def __catch_key(self, return_to_browser=False):
        self.pressedkey = self.get_key(self.term_window)
        for hotkey in self._hotkeys:
            if self.pressedkey == ord(hotkey) and 'switch' in self._hotkeys[hotkey]:
                setattr(self.args,
                        self._hotkeys[hotkey]['switch'],
                        not getattr(self.args,
                                    self._hotkeys[hotkey]['switch']))
            if self.pressedkey == ord(hotkey) and 'sort_key' in self._hotkeys[hotkey]:
                glances_processes.set_sort_key(self._hotkeys[hotkey]['sort_key'],
                                               self._hotkeys[hotkey]['sort_key'] == 'auto')
        if self.pressedkey == ord('\n'):
            self.edit_filter = not self.edit_filter
        elif self.pressedkey == ord('4'):
            self.args.full_quicklook = not self.args.full_quicklook
            if self.args.full_quicklook:
                self.enable_fullquicklook()
            else:
                self.disable_fullquicklook()
        elif self.pressedkey == ord('5'):
            self.args.disable_top = not self.args.disable_top
            if self.args.disable_top:
                self.disable_top()
            else:
                self.enable_top()
        elif self.pressedkey == ord('e'):
            self.args.enable_process_extended = not self.args.enable_process_extended
            if not self.args.enable_process_extended:
                glances_processes.disable_extended()
            else:
                glances_processes.enable_extended()
        elif self.pressedkey == ord('E'):
            glances_processes.process_filter = None
        elif self.pressedkey == ord('f'):
            self.args.disable_fs = not self.args.disable_fs
            self.args.disable_folders = not self.args.disable_folders
        elif self.pressedkey == ord('k'):
            self.kill_process = not self.kill_process
        elif self.pressedkey == ord('w'):
            glances_events.clean()
        elif self.pressedkey == ord('x'):
            glances_events.clean(critical=True)
        elif self.pressedkey == ord('z'):
            self.args.disable_process = not self.args.disable_process
            if self.args.disable_process:
                glances_processes.disable()
            else:
                glances_processes.enable()
        elif self.pressedkey == curses.KEY_LEFT:
            next_sort = (self.loop_position() - 1) % len(self._sort_loop)
            glances_processes.set_sort_key(self._sort_loop[next_sort], False)
        elif self.pressedkey == curses.KEY_RIGHT:
            next_sort = (self.loop_position() + 1) % len(self._sort_loop)
            glances_processes.set_sort_key(self._sort_loop[next_sort], False)
        elif self.pressedkey == curses.KEY_UP or self.pressedkey == 65:
            if self.args.cursor_position > 0:
                self.args.cursor_position -= 1
        elif self.pressedkey == curses.KEY_DOWN or self.pressedkey == 66:
            if self.args.cursor_position < glances_processes.processes_count:
                self.args.cursor_position += 1
        elif self.pressedkey == ord('\x1b') or self.pressedkey == ord('q'):
            if return_to_browser:
                logger.info("Stop Glances client and return to the browser")
            else:
                logger.info(
                    "Stop Glances (keypressed: {})".format(self.pressedkey))
        elif self.pressedkey == curses.KEY_F5:
            pass
        return self.pressedkey
    def __display_top(self, stat_display, stats):
        """Display the second line in the Curses interface.
        <QUICKLOOK> + CPU|PERCPU + <GPU> + MEM + SWAP + LOAD
        """
        self.init_column()
        self.new_line()
        stat_display['quicklook'] = {'msgdict': []}
        plugin_widths = {}
        for p in self._top:
            plugin_widths[p] = self.get_stats_display_width(stat_display.get(p, 0)) if hasattr(self.args, 'disable_' + p) else 0
        stats_width = sum(itervalues(plugin_widths))
        stats_number = sum([int(stat_display[p]['msgdict'] != []) for p in self._top if not getattr(self.args, 'disable_' + p)])
        if not self.args.disable_quicklook:
            if self.args.full_quicklook:
                quicklook_width = self.term_window.getmaxyx()[1] - (stats_width + 8 + stats_number * self.space_between_column)
            else:
                quicklook_width = min(self.term_window.getmaxyx()[1] - (stats_width + 8 + stats_number * self.space_between_column),
                                      self._quicklook_max_width - 5)
            try:
                stat_display["quicklook"] = stats.get_plugin(
                    'quicklook').get_stats_display(max_width=quicklook_width, args=self.args)
            except AttributeError as e:
                logger.debug("Quicklook plugin not available (%s)" % e)
            else:
                plugin_widths['quicklook'] = self.get_stats_display_width(stat_display["quicklook"])
                stats_width = sum(itervalues(plugin_widths)) + 1
            self.space_between_column = 1
            self.display_plugin(stat_display["quicklook"])
            self.new_column()
        plugin_display_optional = {}
        for p in self._top:
            plugin_display_optional[p] = True
        if stats_number > 1:
            self.space_between_column = max(1, int((self.term_window.getmaxyx()[1] - stats_width) / (stats_number - 1)))
            for p in ['mem', 'cpu']:
                if self.space_between_column < 3:
                    plugin_display_optional[p] = False
                    plugin_widths[p] = self.get_stats_display_width(stat_display[p], without_option=True) if hasattr(self.args, 'disable_' + p) else 0
                    stats_width = sum(itervalues(plugin_widths)) + 1
                    self.space_between_column = max(1, int((self.term_window.getmaxyx()[1] - stats_width) / (stats_number - 1)))
        else:
            self.space_between_column = 0
        for p in self._top:
            if p == 'quicklook':
                continue
            if p in stat_display:
                self.display_plugin(stat_display[p],
                                    display_optional=plugin_display_optional[p])
            if p != 'load':
                self.new_column()
        self.space_between_column = 3
        self.saved_line = self.next_line
    def get_stats_display_width(self, curse_msg, without_option=False):
        """Return the width of the formatted curses message."""
        try:
            if without_option:
                c = len(max(''.join([(u(u(nativestr(i['msg'])).encode('ascii', 'replace')) if not i['optional'] else "")
                                     for i in curse_msg['msgdict']]).split('\n'), key=len))
            else:
                c = len(max(''.join([u(u(nativestr(i['msg'])).encode('ascii', 'replace'))
                                     for i in curse_msg['msgdict']]).split('\n'), key=len))
        except Exception as e:
            logger.debug('ERROR: Can not compute plugin width ({})'.format(e))
            return 0
        else:
            return c
    def get_stats_display_height(self, curse_msg):
        r"""Return the height of the formatted curses message.
        The height is defined by the number of '\n' (new line).
        """
        try:
            c = [i['msg'] for i in curse_msg['msgdict']].count('\n')
        except Exception as e:
            logger.debug('ERROR: Can not compute plugin height ({})'.format(e))
            return 0
        else:
            return c + 1
class GlancesClient(object):
    def __init__(self, config=None, args=None, timeout=7, return_to_browser=False):
        self.args = args
        self.config = config
        self._quiet = args.quiet
        self._client_mode = 'glances'
        self.return_to_browser = return_to_browser
        if args.password != "":
            self.uri = 'http://{}:{}@{}:{}'.format(args.username, args.password,
                                                   args.client, args.port)
        else:
            self.uri = 'http://{}:{}'.format(args.client, args.port)
        logger.debug("Try to connect to {}".format(self.uri))
        transport = GlancesClientTransport()
        transport.set_timeout(timeout)
        try:
            self.client = ServerProxy(self.uri, transport=transport)
        except Exception as e:
            self.log_and_exit("Client couldn't create socket {}: {}".format(self.uri, e))
    def update(self):
        """Update stats from Glances/SNMP server."""
        if self.client_mode == 'glances':
            return self.update_glances()
        elif self.client_mode == 'snmp':
            return self.update_snmp()
        else:
            self.end()
            logger.critical("Unknown server mode: {}".format(self.client_mode))
            sys.exit(2)
class GlancesProcesses(object):
    def update(self):
        """Update the processes stats."""
        self.processlist = []
        self.reset_processcount()
        if self.disable_tag:
            return
        time_since_update = getTimeSinceLastUpdate('process_disk')
        standard_attrs = ['cmdline', 'cpu_percent', 'cpu_times', 'memory_info',
                          'memory_percent', 'name', 'nice', 'pid', 'ppid',
                          'status', 'username', 'status', 'num_threads']
        if not self.disable_io_counters:
            standard_attrs += ['io_counters']
        if not self.disable_gids:
            standard_attrs += ['gids']
        self.processlist = [p.info for p in psutil.process_iter(attrs=standard_attrs,
                                                                ad_value=None)
                            if not (BSD and p.info['name'] == 'idle') and
                            not (WINDOWS and p.info['name'] == 'System Idle Process') and
                            not (MACOS and p.info['name'] == 'kernel_task') and
                            not (self.no_kernel_threads and LINUX and p.info['gids'].real == 0) and
                            not (self._filter.is_filtered(p.info))]
        self.processlist = sort_stats(self.processlist,
                                      sortedby=self.sort_key,
                                      reverse=True)
        self.update_processcount(self.processlist)
        first = True
        for proc in self.processlist:
            if first and not self.disable_extended_tag:
                extended = {}
                try:
                    top_process = psutil.Process(proc['pid'])
                    extended_stats = ['cpu_affinity', 'ionice',
                                      'num_ctx_switches']
                    if LINUX:
                        extended_stats += ['num_fds']
                    if WINDOWS:
                        extended_stats += ['num_handles']
                    extended = top_process.as_dict(attrs=extended_stats,
                                                   ad_value=None)
                    if LINUX:
                        try:
                            extended['memory_swap'] = sum([v.swap for v in top_process.memory_maps()])
                        except (psutil.NoSuchProcess, KeyError):
                            pass
                        except (psutil.AccessDenied, NotImplementedError):
                            extended['memory_swap'] = None
                    try:
                        extended['tcp'] = len(top_process.connections(kind="tcp"))
                        extended['udp'] = len(top_process.connections(kind="udp"))
                    except (psutil.AccessDenied, psutil.NoSuchProcess):
                        extended['tcp'] = None
                        extended['udp'] = None
                except (psutil.NoSuchProcess, ValueError, AttributeError) as e:
                    logger.error('Can not grab extended stats ({})'.format(e))
                    extended['extended_stats'] = False
                else:
                    logger.debug('Grab extended stats for process {}'.format(proc['pid']))
                    extended['extended_stats'] = True
                proc.update(extended)
            first = False
            proc['time_since_update'] = time_since_update
            proc['status'] = str(proc['status'])[:1].upper()
            if 'io_counters' in proc and proc['io_counters'] is not None:
                io_new = [proc['io_counters'].read_bytes,
                          proc['io_counters'].write_bytes]
                try:
                    proc['io_counters'] = io_new + self.io_old[proc['pid']]
                    io_tag = 1
                except KeyError:
                    proc['io_counters'] = io_new + [0, 0]
                    io_tag = 0
                self.io_old[proc['pid']] = io_new
            else:
                proc['io_counters'] = [0, 0] + [0, 0]
                io_tag = 0
            proc['io_counters'] += [io_tag]
        for k in self._max_values_list:
            values_list = [i[k] for i in self.processlist if i[k] is not None]
            if values_list != []:
                self.set_max_values(k, max(values_list))
class Plugin(GlancesPlugin):
    def __init__(self,
                 args=None,
                 config=None,
                 stats_init_value=[]):
        """Init the plugin."""
        if not is_admin():
            disable(args, "smart")
            logger.debug("Current user is not admin, HDD SMART plugin disabled.")
        super(Plugin, self).__init__(args=args, config=config)
        self.display_curse = True
class Plugin(GlancesPlugin):
    @GlancesPlugin._check_decorator
    @GlancesPlugin._log_result_decorator
    def update(self):
        """Update sensors stats using the input method."""
        stats = self.get_init_value()
        if self.input_method == 'local':
            stats = []
            try:
                temperature = self.__set_type(self.glancesgrabsensors.get('temperature_core'),
                                              'temperature_core')
            except Exception as e:
                logger.error("Cannot grab sensors temperatures (%s)" % e)
            else:
                stats.extend(temperature)
            try:
                fan_speed = self.__set_type(self.glancesgrabsensors.get('fan_speed'),
                                            'fan_speed')
            except Exception as e:
                logger.error("Cannot grab FAN speed (%s)" % e)
            else:
                stats.extend(fan_speed)
            try:
                hddtemp = self.__set_type(self.hddtemp_plugin.update(),
                                          'temperature_hdd')
            except Exception as e:
                logger.error("Cannot grab HDD temperature (%s)" % e)
            else:
                stats.extend(hddtemp)
            try:
                batpercent = self.__set_type(self.batpercent_plugin.update(),
                                             'battery')
            except Exception as e:
                logger.error("Cannot grab battery percent (%s)" % e)
            else:
                stats.extend(batpercent)
        elif self.input_method == 'snmp':
            pass
        self.stats = self.get_init_value()
        for stat in stats:
            if self.is_hide(stat["label"].lower()):
                continue
            alias = self.has_alias(stat["label"].lower())
            if alias:
                stat["label"] = alias
            self.stats.append(stat)
        return self.stats
class GlancesGrabSensors(object):
    def get(self, sensor_type='temperature_core'):
        """Get sensors list."""
        self.__update__()
        if sensor_type == 'temperature_core':
            ret = [s for s in self.sensors_list if s['unit'] == SENSOR_TEMP_UNIT]
        elif sensor_type == 'fan_speed':
            ret = [s for s in self.sensors_list if s['unit'] == SENSOR_FAN_UNIT]
        else:
            logger.debug("Unknown sensor type %s" % sensor_type)
            ret = []
        return ret
class GlancesClientBrowser(object):
    def __display_server(self, server):
        """
        Connect and display the given server
        """
        logger.debug("Selected server {}".format(server))
        self.screen.display_popup(
            'Connect to {}:{}'.format(server['name'], server['port']), duration=1)
        if server['password'] is None:
            clear_password = self.password.get_password(server['name'])
            if (clear_password is None or self.get_servers_list()
                    [self.screen.active_server]['status'] == 'PROTECTED'):
                clear_password = self.screen.display_popup(
                    'Password needed for {}: '.format(server['name']), is_input=True)
            if clear_password is not None:
                self.set_in_selected('password', self.password.sha256_hash(clear_password))
        logger.info("Connect Glances client to the {} server".format(server['key']))
        args_server = self.args
        args_server.client = server['ip']
        args_server.port = server['port']
        args_server.username = server['username']
        args_server.password = server['password']
        client = GlancesClient(config=self.config, args=args_server, return_to_browser=True)
        if not client.login():
            self.screen.display_popup(
                "Sorry, cannot connect to '{}'\n"
                "See '{}' for more details".format(server['name'], LOG_FILENAME))
            self.set_in_selected('status', 'OFFLINE')
        else:
            connection_type = client.serve_forever()
            try:
                logger.debug("Disconnect Glances client from the {} server".format(server['key']))
            except IndexError:
                pass
            else:
                if connection_type == 'snmp':
                    self.set_in_selected('status', 'SNMP')
                else:
                    self.set_in_selected('status', 'ONLINE')
        self.screen.active_server = None
class GlancesCursesBrowser(_GlancesCurses):
    def __catch_key(self, stats):
        self.pressedkey = self.get_key(self.term_window)
        refresh = False
        if self.pressedkey != -1:
            logger.debug("Key pressed. Code=%s" % self.pressedkey)
        if self.pressedkey == ord('\x1b') or self.pressedkey == ord('q'):
            self.end()
            logger.info("Stop Glances client browser")
            self.is_end = True
        elif self.pressedkey == 10:
            self.active_server =  self._current_page * self._page_max_lines + self.cursor_position
            logger.debug("Server {}/{} selected".format(self.active_server, len(stats)))
        elif self.pressedkey == curses.KEY_UP or self.pressedkey == 65:
            self.cursor_up(stats)
            logger.debug("Server {}/{} selected".format(self.cursor + 1, len(stats)))
        elif self.pressedkey == curses.KEY_DOWN or self.pressedkey == 66:
            self.cursor_down(stats)
            logger.debug("Server {}/{} selected".format(self.cursor + 1, len(stats)))
        elif self.pressedkey == curses.KEY_PPAGE:
            self.cursor_pageup(stats)
            logger.debug("PageUP: Server ({}/{}) pages.".format(self._current_page + 1, self._page_max))
        elif self.pressedkey == curses.KEY_NPAGE:
            self.cursor_pagedown(stats)
            logger.debug("PageDown: Server {}/{} pages".format(self._current_page + 1, self._page_max))
        elif self.pressedkey == ord('1'):
            self._stats_list = None
            refresh = True
        elif self.pressedkey == ord('2'):
            self._revesed_sorting = False
            self._stats_list = stats.copy()
            refresh = True
        elif self.pressedkey == ord('3'):
            self._revesed_sorting = True
            self._stats_list = stats.copy()
            refresh = True
        if refresh:
            self._current_page = 0
            self.cursor_position = 0
            self.flush(stats)
        return self.pressedkey
    def update(self,
               stats,
               duration=3,
               cs_status=None,
               return_to_browser=False):
        """Update the servers' list screen.
        Wait for __refresh_time sec / catch key every 100 ms.
        stats: Dict of dict with servers stats
        """
        logger.debug('Servers list: {}'.format(stats))
        self.flush(stats)
        exitkey = False
        countdown = Timer(self.__refresh_time)
        while not countdown.finished() and not exitkey:
            pressedkey = self.__catch_key(stats)
            exitkey = (
                pressedkey == ord('\x1b') or pressedkey == ord('q') or pressedkey == 10)
            if not exitkey and pressedkey > -1:
                self.flush(stats)
            self.wait()
        return self.active_server
