class PasswordHasherAvailability(Enum):
    LEGACY = 'legacy'
PASSWORD_HASHERS_ALL = {
    'CRYPT-PW': des_crypt,
    'MD5-PW': md5_crypt,
    'BCRYPT-PW': bcrypt,
