                trailer = self.trailer + s
                if trailer.startswith(b"\r\n"):
                    self.completed = True
                    return orig_size - (len(trailer) - 2)
                pos = find_double_newline(trailer)
                if pos < 0:
                    self.trailer = trailer
                    s = b""
                else:
                    self.completed = True
                    self.trailer = trailer[:pos]
                    return orig_size - (len(trailer) - pos)
        return orig_size

